sql.where:
latitude BETWEEN #{southWestLat} AND #{northEastLat}
AND longitude BETWEEN #{southWestLng} AND #{northEastLng}

 AND sido_code = #{sido} 
 AND gugun_code = #{guguns} 
 AND content_type_id = #{contenttype} 

    AND MATCH(title) AGAINST(#{keyword} IN BOOLEAN MODE)

mapper.select:
SELECT attr_id AS attractionId, 1 AS count, latitude AS latitude, longitude AS longitude, title AS title, addr1 AS address, first_image1 AS imageUrl, view_count AS viewCount, like_count AS likeCount, content_type_id AS contentTypeId FROM attractions
ORDER BY like_count DESC, view_count DESC, attr_id DESC
LIMIT #{limit} OFFSET #{offset}
